<?php include '../includes/header.php';$u=user();if(is_admin()){$r=mysqli_query($conn,"SELECT o.*,u.name submitted_name FROM operational_reports o JOIN users u ON u.id=o.submitted_by ORDER BY report_date DESC,id DESC");}else{$s=mysqli_prepare($conn,"SELECT o.*,u.name submitted_name FROM operational_reports o JOIN users u ON u.id=o.submitted_by WHERE o.institution_type=? AND o.institution_code=? ORDER BY report_date DESC,id DESC");mysqli_stmt_bind_param($s,'ss',$u['institution_type'],$u['institution_code']);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);}?>
<div class="page-head"><div><p class="eyebrow">REPORTING</p><h1>Operational Reports</h1></div><?php if(!is_admin()):?><a class="btn primary" href="create.php">+ Daily Report</a><?php endif;?></div>
<div class="card table-wrap"><table><tr><th>Date</th><th>Institution</th><th>Attendance</th><th>Work</th><th>Verification</th><th>Submitted by</th><?php if(is_admin()):?><th>Action</th><?php endif;?></tr><?php while($x=mysqli_fetch_assoc($r)):?><tr><td><?=e($x['report_date'])?></td><td><?=e($x['institution_code'])?></td><td><?=e($x['present'].' / '.$x['total_students'])?> <small>(<?=e($x['absent'])?> absent)</small></td><td><?=e($x['work_status'])?></td><td><span class="pill"><?=e($x['verification_status'])?></span></td><td><?=e($x['submitted_name'])?></td><?php if(is_admin()):?><td><a href="verify.php?id=<?=$x['id']?>">Review</a></td><?php endif;?></tr><?php endwhile;?></table></div><?php include '../includes/footer.php';?>
